import { writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

import type { HtmlTagDescriptor, Plugin, ResolvedConfig } from "vite";

type BrowserSurface = "console" | "stage";

const sharedDirectives = [
  "default-src 'self'",
  "script-src 'self'",
  "style-src 'self'",
  "img-src 'self' data:",
  "connect-src 'self'",
  "worker-src 'self'",
  "manifest-src 'self'",
  "base-uri 'none'",
  "frame-ancestors 'none'",
] as const;

export function createContentSecurityPolicy(surface: BrowserSurface) {
  const formAction = surface === "console" ? "form-action 'self'" : "form-action 'none'";
  return [...sharedDirectives, formAction].join("; ");
}

/**
 * The dev server alone relaxes script-src/style-src.
 *
 * Vite injects its HMR preamble as an inline script and its plugins inject inline styles;
 * under the shipped `script-src 'self'` the preamble is blocked and React never boots, so
 * `vite dev` renders a blank page. This allowance exists only in the dev server response and
 * is never written to the deployment headers or the built artifact.
 */
export function createDevelopmentContentSecurityPolicy(surface: BrowserSurface) {
  return createContentSecurityPolicy(surface)
    .replace("script-src 'self'", "script-src 'self' 'unsafe-inline'")
    .replace("style-src 'self'", "style-src 'self' 'unsafe-inline'");
}

export function createContentSecurityPolicyMeta(surface: BrowserSurface): HtmlTagDescriptor {
  const policy = createContentSecurityPolicy(surface).replace("; frame-ancestors 'none'", "");
  return {
    tag: "meta",
    attrs: {
      "http-equiv": "Content-Security-Policy",
      content: policy,
    },
    injectTo: "head-prepend",
  };
}

export function createDeploymentHeaders(surface: BrowserSurface) {
  return `/*\n  Content-Security-Policy: ${createContentSecurityPolicy(surface)}\n`;
}

export function responseSecurityHeaders(surface: BrowserSurface): Plugin {
  let resolvedConfig: ResolvedConfig;
  const headers = {
    "Content-Security-Policy": createContentSecurityPolicy(surface),
  };
  const developmentHeaders = {
    "Content-Security-Policy": createDevelopmentContentSecurityPolicy(surface),
  };

  return {
    name: `impromptu-${surface}-response-security`,
    config(_userConfig, environment) {
      return {
        preview: { headers },
        server: { headers: environment.command === "serve" ? developmentHeaders : headers },
      };
    },
    configResolved(config) {
      resolvedConfig = config;
    },
    transformIndexHtml(html) {
      if (resolvedConfig.command === "serve") return html;
      return { html, tags: [createContentSecurityPolicyMeta(surface)] };
    },
    closeBundle() {
      const outputDirectory = resolve(resolvedConfig.root, resolvedConfig.build.outDir);
      writeFileSync(join(outputDirectory, "_headers"), createDeploymentHeaders(surface));
    },
  };
}

import { describe, expect, test } from "bun:test";

import {
  createContentSecurityPolicy,
  createContentSecurityPolicyMeta,
  createDeploymentHeaders,
  createDevelopmentContentSecurityPolicy,
} from "./securityHeaders";

const preservedDirectives = [
  "default-src 'self'",
  "script-src 'self'",
  "style-src 'self'",
  "img-src 'self' data:",
  "connect-src 'self'",
  "worker-src 'self'",
  "manifest-src 'self'",
  "base-uri 'none'",
] as const;

describe("browser response security headers", () => {
  test("preserves each CSP directive and denies all frame ancestors", () => {
    for (const surface of ["console", "stage"] as const) {
      const policy = createContentSecurityPolicy(surface);
      for (const directive of preservedDirectives) {
        expect(policy).toContain(directive);
      }
      expect(policy).toContain("frame-ancestors 'none'");
      expect(policy).toContain(surface === "console" ? "form-action 'self'" : "form-action 'none'");
    }
  });

  test("emits the same CSP as a deployment response-header artifact", () => {
    for (const surface of ["console", "stage"] as const) {
      const policy = createContentSecurityPolicy(surface);
      expect(createDeploymentHeaders(surface)).toBe(`/*\n  Content-Security-Policy: ${policy}\n`);
    }
  });

  test("keeps the shipped policy script-src exact and confines the dev allowance to the dev server", () => {
    for (const surface of ["console", "stage"] as const) {
      const shipped = createContentSecurityPolicy(surface);
      const development = createDevelopmentContentSecurityPolicy(surface);

      // The shipped artifact must never gain an inline-script allowance.
      expect(shipped).toContain("script-src 'self'");
      expect(shipped).not.toContain("unsafe-inline");
      expect(createDeploymentHeaders(surface)).not.toContain("unsafe-inline");

      // Vite's dev HMR preamble is an inline script, so the dev server alone relaxes script-src.
      expect(development).toContain("script-src 'self' 'unsafe-inline'");
      expect(development).toContain("style-src 'self' 'unsafe-inline'");

      // Nothing else may differ between the two policies.
      const normalise = (policy: string) =>
        policy
          .split("; ")
          .map((directive) => directive.replace(" 'unsafe-inline'", ""))
          .join("; ");
      expect(normalise(development)).toBe(normalise(shipped));
    }
  });

  test("builds the production index meta from the shipped policy", () => {
    const shipped =
      "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; worker-src 'self'; manifest-src 'self'; base-uri 'none'; form-action 'self'";
    expect(createContentSecurityPolicyMeta("console")).toEqual({
      tag: "meta",
      attrs: {
        "http-equiv": "Content-Security-Policy",
        content: shipped,
      },
      injectTo: "head-prepend",
    });
    expect(shipped).not.toContain("unsafe-inline");
  });
});

import {
  buildEffectKeyframes,
  computeGroupSchedule,
  entranceTargetIds,
  type RuntimeKeyframe,
} from "./animation.ts";
import { DeckNotAnimatableError, MissingTargetError, SlideRuntimeError } from "./errors.ts";
import type { SlideTimeline, UnsupportedEffect } from "./timeline.ts";

export * from "./animation.ts";
export * from "./errors.ts";

export interface RuntimeAnimationOptions {
  readonly delay: number;
  readonly duration: number;
  readonly easing: string;
  readonly fill: "forwards";
}

export interface RuntimeAnimation {
  readonly finished: Promise<unknown>;
  cancel(): void;
}

export interface RuntimeAnimationElement {
  getAttribute(name: string): string | null;
  setAttribute(name: string, value: string): void;
  removeAttribute(name: string): void;
  /**
   * The descendants that actually carry paint. LibreOffice puts `fill` on the drawn
   * `path`/`rect` nodes, never on the group we target by id, so a colour animation applied
   * to the group would be silently ignored.
   */
  paintTargets(): readonly RuntimeAnimationElement[];
  animate(
    keyframes: readonly RuntimeKeyframe[],
    options: RuntimeAnimationOptions,
  ): RuntimeAnimation;
}

export interface RuntimeSvgRoot {
  readonly width: number;
  readonly height: number;
  getElementById(id: string): RuntimeAnimationElement | null;
}

export interface SlidePlayer {
  readonly groupCount: number;
  readonly currentGroup: number;
  readonly skipped: readonly UnsupportedEffect[];
  readonly state: "ready" | "playing" | "finished";
  advance(): Promise<void>;
  reset(): void;
}

interface PlayerOptions {
  readonly timeline: SlideTimeline;
  readonly allowUnsupported?: boolean;
}

interface RuntimePlayerOptions extends PlayerOptions {
  readonly root: RuntimeSvgRoot;
}

export interface CreateSlidePlayerOptions extends PlayerOptions {
  readonly svgRoot: SVGSVGElement;
}

interface TargetState {
  readonly element: RuntimeAnimationElement;
  readonly visibility: string | null;
}

class SlidePlayerController implements SlidePlayer {
  readonly groupCount: number;
  readonly skipped: readonly UnsupportedEffect[];
  private readonly targets = new Map<string, TargetState>();
  private readonly animations = new Set<RuntimeAnimation>();
  private groupIndex = 0;
  private playbackState: SlidePlayer["state"];

  constructor(
    private readonly root: RuntimeSvgRoot,
    private readonly timeline: SlideTimeline,
    allowUnsupported: boolean,
  ) {
    if (timeline.unsupported.length > 0 && !allowUnsupported) {
      throw new DeckNotAnimatableError();
    }
    if (root.width <= 0 || root.height <= 0) {
      throw new SlideRuntimeError("invalid_view_box", "The slide SVG viewBox must be positive");
    }
    this.groupCount = timeline.click_groups.length;
    this.skipped = allowUnsupported ? timeline.unsupported : [];
    this.playbackState = this.groupCount === 0 ? "finished" : "ready";
    for (const group of timeline.click_groups) {
      for (const effect of group) this.resolveTarget(effect.target.svg_element_id);
    }
    this.prepare();
  }

  get currentGroup(): number {
    return this.groupIndex;
  }

  get state(): SlidePlayer["state"] {
    return this.playbackState;
  }

  async advance(): Promise<void> {
    if (this.playbackState === "playing") {
      throw new SlideRuntimeError("player_busy", "The current click group is still playing");
    }
    const group = this.timeline.click_groups[this.groupIndex];
    if (group === undefined) {
      this.playbackState = "finished";
      return;
    }
    this.playbackState = "playing";
    const completions: Promise<unknown>[] = [];
    try {
      let previousAnimation: RuntimeAnimation | undefined;
      for (const scheduled of computeGroupSchedule(group)) {
        if (scheduled.effect.trigger === "after_previous" && previousAnimation !== undefined) {
          await previousAnimation.finished;
        }
        const id = scheduled.effect.target.svg_element_id;
        const target = this.targets.get(id);
        if (target === undefined) throw new MissingTargetError(id);
        if (scheduled.effect.effect_class === "entrance") {
          target.element.setAttribute("visibility", "visible");
        }
        const keyframes = buildEffectKeyframes(scheduled.effect, this.root);
        const options = {
          duration: scheduled.effect.duration_ms,
          delay: scheduled.effect.delay_ms,
          fill: "forwards",
          easing: "linear",
        } as const;
        const painted =
          scheduled.effect.behavior.kind === "color"
            ? target.element.paintTargets()
            : [target.element];
        let animation: RuntimeAnimation | undefined;
        for (const node of painted) {
          animation = node.animate(keyframes, options);
          this.animations.add(animation);
          completions.push(animation.finished);
        }
        previousAnimation = animation ?? previousAnimation;
      }
      await Promise.all(completions);
    } catch (error) {
      this.playbackState = "ready";
      throw error;
    }
    this.groupIndex += 1;
    this.playbackState = this.groupIndex === this.groupCount ? "finished" : "ready";
  }

  reset(): void {
    for (const animation of this.animations) animation.cancel();
    this.animations.clear();
    for (const target of this.targets.values()) {
      if (target.visibility === null) target.element.removeAttribute("visibility");
      else target.element.setAttribute("visibility", target.visibility);
    }
    this.groupIndex = 0;
    this.playbackState = this.groupCount === 0 ? "finished" : "ready";
    this.prepare();
  }

  private prepare(): void {
    for (const id of entranceTargetIds(this.timeline)) {
      this.resolveTarget(id).element.setAttribute("visibility", "hidden");
    }
  }

  private resolveTarget(id: string): TargetState {
    const existing = this.targets.get(id);
    if (existing !== undefined) return existing;
    const element = this.root.getElementById(id);
    if (element === null) throw new MissingTargetError(id);
    const target = { element, visibility: element.getAttribute("visibility") };
    this.targets.set(id, target);
    return target;
  }
}

export function createSlidePlayerFromRoot(options: RuntimePlayerOptions): SlidePlayer {
  return new SlidePlayerController(
    options.root,
    options.timeline,
    options.allowUnsupported === true,
  );
}

const TEXTUAL_SVG_TAGS = ["text", "tspan", "textPath", "altGlyph"] as const;

/**
 * Decide whether one painted SVG node belongs to a colour emphasis.
 *
 * LibreOffice paints a shape's geometry and its label as siblings that both carry `fill`.
 * PowerPoint's change-fill-colour emphasis repaints the shape only, so recolouring the label
 * too would bury the text in its own new background colour.
 */
export function isColourPaintTarget(tagName: string, fill: string | null): boolean {
  if (fill === null || fill === "none") return false;
  const tag = tagName.toLowerCase();
  return !TEXTUAL_SVG_TAGS.some((textual) => textual.toLowerCase() === tag);
}

function wrapElement(element: Element): RuntimeAnimationElement {
  return {
    getAttribute: (name) => element.getAttribute(name),
    setAttribute: (name, value) => element.setAttribute(name, value),
    removeAttribute: (name) => element.removeAttribute(name),
    animate: (keyframes, animationOptions) => element.animate([...keyframes], animationOptions),
    paintTargets: () => {
      const painted = [...element.querySelectorAll("[fill]")].filter((candidate) =>
        isColourPaintTarget(candidate.tagName, candidate.getAttribute("fill")),
      );
      return painted.length > 0 ? painted.map(wrapElement) : [wrapElement(element)];
    },
  };
}

export function createSlidePlayer(options: CreateSlidePlayerOptions): SlidePlayer {
  const svgRoot = options.svgRoot;
  const root: RuntimeSvgRoot = {
    width: svgRoot.viewBox.baseVal.width,
    height: svgRoot.viewBox.baseVal.height,
    getElementById(id) {
      const element = svgRoot.getElementById(id);
      if (element === null) return null;
      return wrapElement(element);
    },
  };
  if (options.allowUnsupported === undefined) {
    return createSlidePlayerFromRoot({ root, timeline: options.timeline });
  }
  return createSlidePlayerFromRoot({
    root,
    timeline: options.timeline,
    allowUnsupported: options.allowUnsupported,
  });
}

import { describe, expect, test } from "bun:test";
import {
  buildEffectKeyframes,
  computeGroupSchedule,
  createSlidePlayerFromRoot,
  entranceTargetIds,
  isColourPaintTarget,
  motionPathToKeyframes,
  type RuntimeAnimation,
  type RuntimeAnimationElement,
  type RuntimeAnimationOptions,
  type RuntimeKeyframe,
  SlideRuntimeError,
} from "./player.ts";
import type { SlideEffect } from "./timeline.ts";
import { parseSlideTimeline } from "./timeline.ts";

const slideKey = `slide_${"b".repeat(64)}`;
function effect(
  id: string,
  trigger: SlideEffect["trigger"],
  behavior: SlideEffect["behavior"],
  durationMs = 100,
  delayMs = 0,
): SlideEffect {
  const timeline = parseSlideTimeline({
    slide_key: slideKey,
    click_groups: [
      [
        {
          trigger,
          effect_class:
            behavior.kind === "motion"
              ? "motion"
              : behavior.kind === "color"
                ? "emphasis"
                : behavior.direction === "out"
                  ? "exit"
                  : "entrance",
          preset_id: 1,
          duration_ms: durationMs,
          delay_ms: delayMs,
          target: { shape_id: 1, shape_name: id, svg_element_id: id },
          behavior,
        },
      ],
    ],
  });
  const parsed = timeline.click_groups[0]?.[0];
  if (parsed === undefined) throw new TypeError("effect fixture was not parsed");
  return parsed;
}
function timeline(
  groups: readonly (readonly SlideEffect[])[],
  unsupported: readonly object[] = [],
) {
  return parseSlideTimeline({ slide_key: slideKey, click_groups: groups, unsupported });
}
class FakeAnimation implements RuntimeAnimation {
  readonly finished: Promise<void>;
  private finishPlayback = (): void => {};
  constructor(pending: boolean) {
    this.finished = pending
      ? new Promise((resolve) => {
          this.finishPlayback = resolve;
        })
      : Promise.resolve();
  }
  cancel(): void {}
  finish(): void {
    this.finishPlayback();
  }
}
interface AnimationCall {
  readonly id: string;
  readonly keyframes: readonly RuntimeKeyframe[];
  readonly options: RuntimeAnimationOptions;
}
class FakeElement implements RuntimeAnimationElement {
  readonly attributes = new Map<string, string>();
  paints: readonly RuntimeAnimationElement[] = [];
  private readonly animation: FakeAnimation;
  constructor(
    readonly id: string,
    private readonly calls: AnimationCall[],
    pending: boolean,
  ) {
    this.animation = new FakeAnimation(pending);
  }
  paintTargets(): readonly RuntimeAnimationElement[] {
    return this.paints.length > 0 ? this.paints : [this];
  }
  getAttribute(name: string): string | null {
    return this.attributes.get(name) ?? null;
  }
  setAttribute(name: string, value: string): void {
    this.attributes.set(name, value);
  }
  removeAttribute(name: string): void {
    this.attributes.delete(name);
  }
  animate(
    keyframes: readonly RuntimeKeyframe[],
    options: RuntimeAnimationOptions,
  ): RuntimeAnimation {
    this.calls.push({ id: this.id, keyframes, options });
    return this.animation;
  }
  finish(): void {
    this.animation.finish();
  }
}
function fakeRoot(ids: readonly string[], calls: AnimationCall[], pending: readonly string[] = []) {
  const elements = new Map(ids.map((id) => [id, new FakeElement(id, calls, pending.includes(id))]));
  return {
    width: 800,
    height: 600,
    getElementById(id: string) {
      return elements.get(id) ?? null;
    },
    element(id: string) {
      return elements.get(id);
    },
  };
}

describe("player pure logic", () => {
  test("computes entrance preparation targets once", () => {
    const enter = effect("shape-a", "on_click", { kind: "fade", direction: "in" });
    const exit = effect("shape-b", "on_click", { kind: "fade", direction: "out" });
    expect(entranceTargetIds(timeline([[enter], [enter, exit]]))).toEqual(["shape-a"]);
  });

  test("schedules with-previous from the prior start and after-previous from its finish", () => {
    const effects = [
      effect("a", "on_click", { kind: "fade", direction: "in" }, 100, 10),
      effect("b", "with_previous", { kind: "fade", direction: "in" }, 50, 5),
      effect("c", "after_previous", { kind: "fade", direction: "out" }, 20, 7),
    ];
    expect(
      computeGroupSchedule(effects).map(({ start_ms, animation_delay_ms }) => ({
        start_ms,
        animation_delay_ms,
      })),
    ).toEqual([
      { start_ms: 0, animation_delay_ms: 10 },
      { start_ms: 0, animation_delay_ms: 5 },
      { start_ms: 55, animation_delay_ms: 62 },
    ]);
  });

  test("constructs exact fade, wipe, color, and relative motion keyframes", () => {
    expect(
      buildEffectKeyframes(effect("a", "on_click", { kind: "fade", direction: "out" }), {
        width: 800,
        height: 600,
      }),
    ).toEqual([{ opacity: 1 }, { opacity: 0 }]);
    expect(
      buildEffectKeyframes(
        effect("a", "on_click", { kind: "wipe", direction: "in", edge: "left" }),
        { width: 800, height: 600 },
      ),
    ).toEqual([{ clipPath: "inset(0 100% 0 0)" }, { clipPath: "inset(0 0 0 0)" }]);
    expect(
      buildEffectKeyframes(
        effect("a", "on_click", {
          kind: "color",
          from_color: "#112233",
          to_color: "#AABBCC",
        }),
        { width: 800, height: 600 },
      ),
    ).toEqual([{ fill: "#112233" }, { fill: "#AABBCC" }]);
    expect(motionPathToKeyframes("M 0 1 L 0 0 E", { width: 800, height: 600 })).toEqual([
      { transform: "translate(0px, 600px)", offset: 0 },
      { transform: "translate(0px, 0px)", offset: 1 },
    ]);
  });

  test("rejects motion commands that transform keyframes cannot represent exactly", () => {
    expect(() =>
      motionPathToKeyframes("M 0 0 C 0.2 0.3 0.8 0.7 1 1 E", { width: 800, height: 600 }),
    ).toThrow(SlideRuntimeError);
  });
});

describe("slide player", () => {
  test("prepares entrances and drives one click group through the animation surface", async () => {
    const calls: AnimationCall[] = [];
    const root = fakeRoot(["a", "b", "c"], calls, ["b"]);
    const player = createSlidePlayerFromRoot({
      root,
      timeline: timeline([
        [
          effect("a", "on_click", { kind: "fade", direction: "in" }, 100, 10),
          effect(
            "b",
            "with_previous",
            {
              kind: "color",
              from_color: "#112233",
              to_color: "#445566",
            },
            50,
            5,
          ),
          effect("c", "after_previous", { kind: "fade", direction: "out" }, 20, 7),
        ],
      ]),
    });
    expect(root.element("a")?.getAttribute("visibility")).toBe("hidden");
    const advancement = player.advance();
    expect(calls.map(({ id }) => id)).toEqual(["a", "b"]);
    root.element("b")?.finish();
    await advancement;

    expect(calls).toEqual([
      {
        id: "a",
        keyframes: [{ opacity: 0 }, { opacity: 1 }],
        options: { duration: 100, delay: 10, fill: "forwards", easing: "linear" },
      },
      {
        id: "b",
        keyframes: [{ fill: "#112233" }, { fill: "#445566" }],
        options: { duration: 50, delay: 5, fill: "forwards", easing: "linear" },
      },
      {
        id: "c",
        keyframes: [{ opacity: 1 }, { opacity: 0 }],
        options: { duration: 20, delay: 7, fill: "forwards", easing: "linear" },
      },
    ]);
    expect(player.currentGroup).toBe(1);
    expect(player.state).toBe("finished");
  });

  test("colour effects animate the painted descendants, not the wrapping group", async () => {
    const calls: AnimationCall[] = [];
    const root = fakeRoot(["group", "path-1", "path-2"], calls);
    const group = root.element("group");
    const first = root.element("path-1");
    const second = root.element("path-2");
    if (group === undefined || first === undefined || second === undefined) {
      throw new TypeError("fake elements missing");
    }
    group.paints = [first, second];
    const player = createSlidePlayerFromRoot({
      root,
      timeline: timeline([
        [
          effect(
            "group",
            "on_click",
            { kind: "color", from_color: "#0070C0", to_color: "#FF0000" },
            400,
          ),
        ],
      ]),
    });

    await player.advance();

    expect(calls.map(({ id }) => id)).toEqual(["path-1", "path-2"]);
    expect(calls[0]?.keyframes).toEqual([{ fill: "#0070C0" }, { fill: "#FF0000" }]);
  });

  test("fails closed for unsupported effects and reports missing SVG targets", () => {
    const root = fakeRoot([], []);
    expect(() =>
      createSlidePlayerFromRoot({
        root,
        timeline: timeline([], [{ reason_code: "unsupported_preset", detail: "unknown" }]),
      }),
    ).toThrow(SlideRuntimeError);
    expect(() =>
      createSlidePlayerFromRoot({
        root,
        timeline: timeline([[effect("missing", "on_click", { kind: "fade", direction: "in" })]]),
      }),
    ).toThrow(SlideRuntimeError);
  });

  test("colour targets cover shape geometry but never the shape's own text", () => {
    // LibreOffice paints a shape as <path fill="..."> and its label as <tspan fill="...">.
    // PowerPoint's "change fill colour" emphasis recolours the shape only; recolouring the
    // label too would hide the text behind its own background.
    const geometry = ["path", "rect", "ellipse", "polygon", "circle"];
    const textual = ["text", "tspan"];

    for (const tag of geometry) {
      expect(isColourPaintTarget(tag, "rgb(0,112,192)")).toBe(true);
    }
    for (const tag of textual) {
      expect(isColourPaintTarget(tag, "rgb(255,255,255)")).toBe(false);
    }
    expect(isColourPaintTarget("path", "none")).toBe(false);
    expect(isColourPaintTarget("path", null)).toBe(false);
  });
});

